const input = $input.first().json;
const execution = input.execution || {};
const error = execution.error || input.error || {};

// Extract execution details - execution.url is the direct link to this execution
const executionId = execution.id || 'N/A';
const workflowId = execution.workflowId || 'N/A';
const workflowName = execution.workflowName || 'shopify-support-handler';
const failedNode = execution.lastNodeExecuted || error.node?.name || 'Unknown Node';
const errorMessage = error.message || error.description || 'No error message';
const executionUrl = execution.url || 'N/A';
const timestamp = new Date().toISOString();

// Extract ticket ID from execution data if available
const runData = execution.data?.resultData?.runData || {};
let ticketId = 'N/A';
for (const nodeName of ['Parse Input', 'Shopify Webhook']) {
  const nodeData = runData[nodeName]?.[0]?.data?.main?.[0]?.[0]?.json;
  if (nodeData?.ticketId) {
    ticketId = nodeData.ticketId;
    break;
  }
}

return [{
  json: {
    timestamp,
    workflowId,
    workflowName,
    executionId,
    failedNode,
    errorMessage,
    ticketId,
    executionUrl,
    errorDetails: JSON.stringify(error, null, 2),
    severity: 'high'
  }
}];
